#!/usr/bin/env python3
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]

def replace_once(path, old, new):
    p = ROOT / path
    s = p.read_text(encoding='utf-8')
    if old not in s:
        raise SystemExit(f'anchor not found in {path}: {old[:100]!r}')
    if s.count(old) != 1:
        raise SystemExit(f'anchor not unique in {path}: {s.count(old)}')
    p.write_text(s.replace(old, new, 1), encoding='utf-8')

# 1) .NET: prefer a target-local, cryptographically verified existing regName RegStr,
# then fall back to product-list evidence extracted from ITMC.Web.dll.
replace_once(
    'src/main/java/LicenseRecoverModernGUIAutoRecovery.java',
    '        String regStr = detectProductList(new File(d.runtimeDir, "ITMC.Web.dll"), product);\n',
    '        String regStr = detectDotNetRegStr(d);\n')

anchor = '''    static String detectProductList(File webDll,String product) {\n        Set<String>s=extractUtf16Ascii(webDll);TreeSet<String> out=new TreeSet<String>();\n        if("itmcIEC".equals(product)){for(String x:s)if(x.matches("DS\\\\d{4}"))out.add(x);}\n        else if(product!=null&&product.matches("YX\\\\d{4}")){for(String x:s)if(x.matches(Pattern.quote(product)+"\\\\d{2}"))out.add(x);}\n        else if(product!=null&&product.matches("GM\\\\d{3}")){for(String x:s)if(x.matches(Pattern.quote(product)+"\\\\d{2}"))out.add(x);}\n        StringBuilder b=new StringBuilder();for(String x:out){if(b.length()>0)b.append(',');b.append(x);}return b.toString();\n    }\n'''
insert = anchor + '''\n    /**\n     * Resolve .NET RegStr only from the selected application directory.  A valid\n     * existing local regName is stronger evidence than string scraping: decrypt it\n     * with the ProName already proven by ITMC.Web.dll, require the embedded ProName\n     * to match, and then reuse its RegStr.  If no valid local license exists, keep\n     * the existing DLL product-list parser as the secondary source.\n     */\n    static String detectDotNetRegStr(Detection d) {\n        if (d == null || blank(d.productName) || d.runtimeDir == null) return null;\n        String local = recoverDotNetLocalRegStr(d.appRoot, d.runtimeDir, d.productName);\n        if (!blank(local)) return local;\n        return detectProductList(new File(d.runtimeDir, "ITMC.Web.dll"), d.productName);\n    }\n\n    static String recoverDotNetLocalRegStr(File root, File runtimeDir, String product) {\n        if (blank(product)) return null;\n        File[] candidates = new File[]{\n                root == null ? null : new File(root, "config.xml"),\n                runtimeDir == null ? null : new File(runtimeDir, "config.xml")\n        };\n        HashSet<String> seen = new HashSet<String>();\n        for (File cfg : candidates) {\n            if (cfg == null || !cfg.isFile()) continue;\n            try {\n                String key = cfg.getCanonicalPath().toLowerCase(Locale.ROOT);\n                if (!seen.add(key)) continue;\n                String encrypted = firstElement(readUtf8(cfg), "regName");\n                if (blank(encrypted)) continue;\n                String plain = desDecryptHex(encrypted.trim(), "*ITMC" + product.trim() + "OK*");\n                int begin = plain.indexOf('{'), end = plain.lastIndexOf('}');\n                if (begin < 0 || end <= begin) continue;\n                String json = plain.substring(begin, end + 1);\n                String embeddedProduct = jsonStringField(json, "ProName");\n                String regStr = normalizeProductCsv(jsonStringField(json, "RegStr"));\n                if (product.trim().equalsIgnoreCase(embeddedProduct) && !blank(regStr)) return regStr;\n            } catch (Throwable ignore) { }\n        }\n        return null;\n    }\n\n    private static String jsonStringField(String json, String name) {\n        if (json == null || name == null) return null;\n        Matcher m = Pattern.compile("(?is)\\\\\"" + Pattern.quote(name)\n                + "\\\\\"\\\\s*:\\s*\\\\\"([^\\\\\"]*)\\\\\"").matcher(json);\n        return m.find() ? m.group(1).trim() : null;\n    }\n\n    private static String normalizeProductCsv(String raw) {\n        if (blank(raw)) return null;\n        LinkedHashSet<String> out = new LinkedHashSet<String>();\n        for (String part : raw.split(",")) {\n            String token = part.trim();\n            if (token.isEmpty()) continue;\n            if (!token.matches("(?i)[A-Z0-9][A-Z0-9._-]{1,63}")) return null;\n            out.add(token.toUpperCase(Locale.ROOT));\n        }\n        if (out.isEmpty()) return null;\n        StringBuilder b = new StringBuilder();\n        for (String token : out) { if (b.length() > 0) b.append(','); b.append(token); }\n        return b.toString();\n    }\n'''
replace_once('src/main/java/LicenseRecoverModernGUIAutoRecovery.java', anchor, insert)

# 2) Batch scan + batch preflight must use the same .NET evidence resolver as execution.
replace_once(
    'src/main/java/LicenseRecoverModernGUI.java',
    '''                            String dotNetRegStr = d.productName == null ? null\n                                    : LicenseRecoverModernGUIAutoRecovery.detectProductList(\n                                            new File(info.binDir, "ITMC.Web.dll"), d.productName);\n''',
    '''                            String dotNetRegStr = d.productName == null ? null\n                                    : LicenseRecoverModernGUIAutoRecovery.detectDotNetRegStr(d);\n''')
replace_once(
    'src/main/java/LicenseRecoverModernGUI.java',
    '''            String products = LicenseRecoverModernGUIAutoRecovery.detectProductList(\n                    new File(target.binDir, "ITMC.Web.dll"), d.productName);\n''',
    '''            String products = LicenseRecoverModernGUIAutoRecovery.detectDotNetRegStr(d);\n''')

# 3) Java YX0305-style config flow: classes/config.xml SoftVersionID is copied into
# PRODUCT_ALL_NUM; ProjectApplicationRunner splits that field and passes each concrete
# id to RegisterMain.checkReInfo().  Accept the concrete id only when both classes prove it.
old = '''        File systemInfo = new File(classes, "com" + File.separator + "itmc" + File.separator\n                + "register" + File.separator + "utils" + File.separator + "SystemInfo.class");\n        File listener = new File(classes, "com" + File.separator + "itmc" + File.separator\n                + "register" + File.separator + "service" + File.separator + "RegisterListener.class");\n        if (!classFileContainsAll(systemInfo, "config.xml", "SystemSoft", "registerId")) return null;\n        if (!classFileContainsAll(listener, "com/itmc/register/utils/SystemInfo", "registerId",\n                "itmc/regedit/RegisterMain", "getRegStr", "versionID", "contains")) return null;\n        return concrete;\n    }\n'''
new = '''        File systemInfo = new File(classes, "com" + File.separator + "itmc" + File.separator\n                + "register" + File.separator + "utils" + File.separator + "SystemInfo.class");\n        File listener = new File(classes, "com" + File.separator + "itmc" + File.separator\n                + "register" + File.separator + "service" + File.separator + "RegisterListener.class");\n        if (classFileContainsAll(systemInfo, "config.xml", "SystemSoft", "registerId")\n                && classFileContainsAll(listener, "com/itmc/register/utils/SystemInfo", "registerId",\n                "itmc/regedit/RegisterMain", "getRegStr", "versionID", "contains")) return concrete;\n\n        // Another target-owned generation (for example YX0305xx) loads\n        // classes/config.xml SoftVersionID into PRODUCT_ALL_NUM and its startup runner\n        // splits that value and feeds every concrete id to RegisterMain.checkReInfo().\n        // The field name alone is not sufficient; both parser and runner bytecode must\n        // expose the complete target-local flow before the concrete VersionID is accepted.\n        if (confirmedProductAllNumRuntimeProduct(classes)) return concrete;\n        return null;\n    }\n\n    static boolean confirmedProductAllNumRuntimeProduct(File classes) {\n        if (classes == null || !classes.isDirectory()) return false;\n        File xmlUtil = new File(classes, "com" + File.separator + "itmc" + File.separator\n                + "utils" + File.separator + "IXmlUtil.class");\n        File runner = new File(classes, "com" + File.separator + "itmc" + File.separator\n                + "utils" + File.separator + "ProjectApplicationRunner.class");\n        return classFileContainsAll(xmlUtil, "global.system.VersionID", "/config.xml",\n                        "SystemSoft", "SoftVersionID", "regInfo", "SYS_PRODUCT_NUM",\n                        "PRODUCT_ALL_NUM", "PRODUCT_INFO")\n                && classFileContainsAll(runner, "PRODUCT_ALL_NUM", "split",\n                        "itmc/regedit/GetRegisterCode", "RegeditNew", "itmcsoft",\n                        "itmc/regedit/RegisterMain", "writeRegisterUser", "checkReInfo");\n    }\n'''
replace_once('src/main/java/LicenseRecoverModernGUIJavaPlan.java', old, new)

# 4) Regression tests: YX0102 local-license RegStr proof + realistic YX030506 config->PRODUCT_ALL_NUM flow.
test_path = ROOT / 'src/test/java/RefactorSmokeTest.java'
s = test_path.read_text(encoding='utf-8')
anchor_test = '''        Path noRegStrFixture = base.resolve("YX0303-no-products-Web.dll");\n        writeUtf16Fixture(noRegStrFixture, "YX0303", "SoftVersionID", "ProName");\n        check(LicenseRecoverModernGUIAutoRecovery.detectProductList(\n                        noRegStrFixture.toFile(), "YX0303").isEmpty(),\n                ".NET directory parser returns empty instead of inventing RegStr");\n'''
insert_test = anchor_test + '''\n        Path yx0102Root = base.resolve("dotnet-YX0102");\n        Path yx0102Bin = yx0102Root.resolve("bin");\n        Files.createDirectories(yx0102Bin);\n        writeUtf16Fixture(yx0102Bin.resolve("ITMC.Web.dll"), "YX0102", "ProName", "RegStr");\n        Files.write(yx0102Bin.resolve("ITMC.Regedit.dll"), new byte[]{1});\n        String yx0102Plain = "877842{\\\"RegStr\\\":\\\"YX0102\\\",\\\"RegID\\\":\\\"F000606A59904719\\\",\\\"UserID\\\":\\\"fwq\\\",\\\"ProName\\\":\\\"YX0102\\\"}708027";\n        String yx0102Cipher = LicenseRecoverModernGUIAutoRecovery.desEncryptHex(\n                yx0102Plain, "*ITMCYX0102OK*");\n        Files.write(yx0102Root.resolve("config.xml"), Arrays.asList(\n                "<ROOT><reg><regType>1</regType><regName>" + yx0102Cipher + "</regName></reg>",\n                "<SystemSoft><SoftVersionID>YX0102</SoftVersionID></SystemSoft></ROOT>"),\n                StandardCharsets.UTF_8);\n        LicenseRecoverModernGUIAutoRecovery.Detection yx0102Detection =\n                LicenseRecoverModernGUIAutoRecovery.detect(yx0102Root.toFile());\n        check("YX0102".equals(yx0102Detection.productName)\n                        && "YX0102".equals(LicenseRecoverModernGUIAutoRecovery.detectDotNetRegStr(yx0102Detection)),\n                "YX0102 recovers RegStr from target-local regName only after ProName-key verification");\n        LicenseRecoverModernGUIAutoRecovery.Detection yx0102WrongProduct =\n                new LicenseRecoverModernGUIAutoRecovery.Detection(\n                        LicenseRecoverModernGUIAutoRecovery.Kind.DOTNET_MODERN,\n                        yx0102Root.toFile(), yx0102Root.toFile(), yx0102Bin.toFile(),\n                        "YX0102", "YX0103");\n        check(LicenseRecoverModernGUIAutoRecovery.detectDotNetRegStr(yx0102WrongProduct) == null,\n                "target-local .NET regName is rejected when its cryptographic ProName does not match");\n'''
if anchor_test not in s:
    raise SystemExit('dotnet test anchor not found')
s = s.replace(anchor_test, insert_test, 1)

old_yx = '''        Files.write(yx305Classes.resolve("RegistrationEvidence.class"),\n                "YX0305 YX030506".getBytes(StandardCharsets.US_ASCII));\n        yx305Plan = LicenseRecoverModernGUIJavaPlan.inspect(yx305Root.toFile());\n        check("YX0305".equals(yx305Plan.authorizationFamily)\n                        && "YX030506".equals(yx305Plan.runtimeProductId)\n                        && yx305Plan.automaticRecoveryReady,\n                "YX0305 family/runtime IDs become ready only with target-binary evidence");\n'''
new_yx = '''        Path yx305Servlet = yx305Classes.resolve("com/itmc/sys/platformregister/RegisterHttpServlet.class");\n        Path yx305XmlUtil = yx305Classes.resolve("com/itmc/utils/IXmlUtil.class");\n        Path yx305Runner = yx305Classes.resolve("com/itmc/utils/ProjectApplicationRunner.class");\n        Files.createDirectories(yx305Servlet.getParent());\n        Files.createDirectories(yx305XmlUtil.getParent());\n        Files.write(yx305Servlet,\n                "YX0305 itmc/regedit/RegisterMain doRegistry".getBytes(StandardCharsets.ISO_8859_1));\n        Files.write(yx305XmlUtil,\n                "global.system.VersionID /config.xml SystemSoft SoftVersionID regInfo SYS_PRODUCT_NUM PRODUCT_ALL_NUM PRODUCT_INFO"\n                        .getBytes(StandardCharsets.ISO_8859_1));\n        Files.write(yx305Runner,\n                "PRODUCT_ALL_NUM split itmc/regedit/RegisterMain checkReInfo"\n                        .getBytes(StandardCharsets.ISO_8859_1));\n        yx305Plan = LicenseRecoverModernGUIJavaPlan.inspect(yx305Root.toFile());\n        check("YX0305".equals(yx305Plan.authorizationFamily)\n                        && yx305Plan.runtimeProductId == null\n                        && !yx305Plan.automaticRecoveryReady,\n                "YX030506 family evidence alone stays blocked when startup PRODUCT_ALL_NUM flow is incomplete");\n        Files.write(yx305Runner,\n                "PRODUCT_ALL_NUM split itmc/regedit/GetRegisterCode RegeditNew itmcsoft itmc/regedit/RegisterMain writeRegisterUser checkReInfo"\n                        .getBytes(StandardCharsets.ISO_8859_1));\n        yx305Plan = LicenseRecoverModernGUIJavaPlan.inspect(yx305Root.toFile());\n        check("YX0305".equals(yx305Plan.authorizationFamily)\n                        && "YX030506".equals(yx305Plan.runtimeProductId)\n                        && "QT100101,QT100102".equals(yx305Plan.regStr)\n                        && yx305Plan.automaticRecoveryReady,\n                "YX030506 runtime id is accepted only from target config->PRODUCT_ALL_NUM->RegisterMain flow");\n'''
if old_yx not in s:
    raise SystemExit('YX030506 test anchor not found')
s = s.replace(old_yx, new_yx, 1)
test_path.write_text(s, encoding='utf-8')

print('YX0102/YX030506 target-directory evidence patch applied')
